const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Polygon([
      [-75.2, 43.5],
      [-73.3, 43.5],
      [-73.3, 45.1],
      [-75.2, 45.1],
      [-75.2, 43.5]
    ], null, false);

    const date1 = '2022-10-01';
    const date2 = '2022-10-08';

    const scale = 1000;

    // Helper: getInfo as Promise
    const getInfo = (eeObj) =>
      new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));

    // Region pixel baseline
    const regionPixels = await getInfo(
      ee.Image(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e10
      }).get('constant')
    );

    // Cloud masking and scaling
    function maskS2(img) {
      const scl = img.select('SCL');
      const keep = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)); // veg, bare, water
      const scaled = img.select(['B2', 'B3', 'B4', 'B8'])
        .divide(10000)
        .clamp(0, 1)
        .rename(['blue', 'green', 'red', 'nir']);
      return scaled.updateMask(keep);
    }

    function maskLandsatL2(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0)) // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0)) // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0)) // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0)); // snow
      const scaled = img.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5'])
        .multiply(0.0000275).add(-0.2).clamp(0, 1)
        .rename(['blue', 'green', 'red', 'nir']);
      return scaled.updateMask(mask);
    }

    // HSV conversion
    function rgbToHsv(img) {
      const r = img.select('red');
      const g = img.select('green');
      const b = img.select('blue');
      const max = r.max(g).max(b);
      const min = r.min(g).min(b);
      const delta = max.subtract(min);

      const zero = ee.Image(0);
      const hueR = g.subtract(b).divide(delta);
      const hueG = b.subtract(r).divide(delta).add(2);
      const hueB = r.subtract(g).divide(delta).add(4);

      let hue = ee.Image(0)
        .where(delta.eq(0), 0)
        .where(delta.neq(0).and(max.eq(r)), hueR)
        .where(delta.neq(0).and(max.eq(g)), hueG)
        .where(delta.neq(0).and(max.eq(b)), hueB)
        .multiply(60);

      hue = hue.mod(360).where(hue.lt(0), hue.add(360)); // 0..360
      const sat = ee.Image(0).where(max.neq(0), delta.divide(max));
      const val = max;
      return img.addBands(hue.rename('hue')).addBands(sat.rename('sat')).addBands(val.rename('val'));
    }

    async function getCompositeForDate(dateStr, region) {
      // Try Sentinel-2 1-day window
      let start = ee.Date(dateStr);
      let end = start.advance(1, 'day');
      let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end);
      let size = await getInfo(col.size());
      if (size === 0) {
        // Widen to +/-3 days (7-day window)
        start = ee.Date(dateStr).advance(-3, 'day');
        end = ee.Date(dateStr).advance(4, 'day');
        col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
          .filterBounds(region)
          .filterDate(start, end);
        size = await getInfo(col.size());
      }
      if (size > 0) {
        const img = col.map(maskS2).median();
        return { img, src: 'S2', imgs: size, windowDays: (await getInfo(end.difference(start, 'day'))) };
      }

      // Fallback: Landsat 8 + 9, 7-day window
      start = ee.Date(dateStr).advance(-3, 'day');
      end = ee.Date(dateStr).advance(4, 'day');
      const col8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(region).filterDate(start, end);
      const col9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(region).filterDate(start, end);
      const merged = col8.merge(col9);
      const lsize = await getInfo(merged.size());
      if (lsize === 0) {
        return { img: null, src: 'NONE', imgs: 0, windowDays: (await getInfo(end.difference(start, 'day'))) };
      }
      const img = merged.map(maskLandsatL2).median();
      return { img, src: 'L8+L9', imgs: lsize, windowDays: (await getInfo(end.difference(start, 'day'))) };
    }

    async function computeOrangeStats(comp, region, regionPixels) {
      if (!comp.img) return { status: 'C1' };
      let img = comp.img;

      // Add indices and HSV
      const withHSV = rgbToHsv(img);
      const ndvi = img.expression('(nir - red) / (nir + red)', {
        nir: img.select('nir'),
        red: img.select('red')
      }).rename('ndvi');
      const ndwi = img.expression('(green - nir) / (green + nir)', {
        green: img.select('green'),
        nir: img.select('nir')
      }).rename('ndwi');

      let base = withHSV.addBands([ndvi, ndwi]);

      // Build masks
      const bandMask = img.mask().reduce(ee.Reducer.min()); // non-cloud valid across bands
      const notWater = ndwi.lt(0.2);
      const goodMask = bandMask.and(notWater);

      const hue = base.select('hue'); // degrees
      const sat = base.select('sat');
      const ndviBand = base.select('ndvi');

      const orangeMask = goodMask
        .and(sat.gt(0.25))
        .and(hue.gte(15)).and(hue.lte(60))
        .and(ndviBand.gt(0.1)).and(ndviBand.lt(0.8));

      const validPx = await getInfo(
        ee.Image(1).updateMask(goodMask).reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e10
        }).get('constant')
      );

      if (!validPx || validPx === 0) return { status: 'C2' };

      const orangePx = await getInfo(
        ee.Image(1).updateMask(orangeMask).reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e10
        }).get('constant')
      );

      if (orangePx === null || orangePx === undefined) return { status: 'C3' };

      const orangePct = (orangePx / validPx) * 100;
      if (!isFinite(orangePct)) return { status: 'C3' };

      const validPct = (validPx / regionPixels) * 100;

      return {
        status: 'OK',
        validPx,
        orangePx,
        orangePct,
        validPct
      };
    }

    // Get composites
    const comp1 = await getCompositeForDate(date1, region);
    const comp2 = await getCompositeForDate(date2, region);

    if ((!comp1.img && comp1.imgs === 0) || (!comp2.img && comp2.imgs === 0)) {
      console.log(`Region px @${scale}m: ${regionPixels}`);
      if (!comp1.img) console.log(`Date ${date1}: src=${comp1.src}, imgs=${comp1.imgs}, windowDays=${comp1.windowDays}`);
      if (!comp2.img) console.log(`Date ${date2}: src=${comp2.src}, imgs=${comp2.imgs}, windowDays=${comp2.windowDays}`);
      console.log('C1');
      return;
    }

    // Compute stats
    const stats1 = await computeOrangeStats(comp1, region, regionPixels);
    const stats2 = await computeOrangeStats(comp2, region, regionPixels);

    if (stats1.status !== 'OK' || stats2.status !== 'OK') {
      console.log(`Region px @${scale}m: ${regionPixels}`);
      if (stats1.status !== 'OK') {
        console.log(`Date ${date1}: src=${comp1.src}, imgs=${comp1.imgs}, windowDays=${comp1.windowDays}, status=${stats1.status}`);
      }
      if (stats2.status !== 'OK') {
        console.log(`Date ${date2}: src=${comp2.src}, imgs=${comp2.imgs}, windowDays=${comp2.windowDays}, status=${stats2.status}`);
      }
      const code = [stats1.status, stats2.status].find(s => s !== 'OK') || 'C3';
      console.log(code);
      return;
    }

    // Print concise evidence for both dates
    console.log(`Date ${date1}: src=${comp1.src}, imgs=${comp1.imgs}, windowDays=${comp1.windowDays}, regionPx=${regionPixels}, validPx=${stats1.validPx} (${stats1.validPct.toFixed(1)}%), orangePx=${stats1.orangePx} (${stats1.orangePct.toFixed(2)}%)`);
    console.log(`Date ${date2}: src=${comp2.src}, imgs=${comp2.imgs}, windowDays=${comp2.windowDays}, regionPx=${regionPixels}, validPx=${stats2.validPx} (${stats2.validPct.toFixed(1)}%), orangePx=${stats2.orangePx} (${stats2.orangePct.toFixed(2)}%)`);

    // Final decision
    const answer = stats2.orangePct > stats1.orangePct ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    try {
      // Attempt to print a minimal diagnostic line within 20-line limit
      console.log(`Error: ${String(err).slice(0, 120)}`);
    } catch (_) {}
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
